import{_ as a,o as t,c as n,a3 as i}from"./chunks/framework.BNNhFWPR.js";const u=JSON.parse('{"title":"Rendering platforms","description":"Which GPU API the engine draws with on each OS, how it is chosen, and what each one needs.","frontmatter":{"id":"rendering","title":"Rendering platforms","order":2,"description":"Which GPU API the engine draws with on each OS, how it is chosen, and what each one needs.","editUrl":"https://github.com/ATMO-Engine/atmo/edit/main/docs/en/manual/rendering.md"},"headers":[],"relativePath":"manual/rendering.md","filePath":"en/manual/rendering.md"}'),r={name:"manual/rendering.md"};function o(d,e,l,s,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="rendering-platforms" tabindex="-1">Rendering platforms <a class="header-anchor" href="#rendering-platforms" aria-label="Permalink to &quot;Rendering platforms&quot;">​</a></h1><p>The <a href="/latest/api/cpp/class/atmo-server-rendering-renderingserver" class="atmo-ref atmo-ref--symbol"><code>RenderingServer</code></a> draws through a <a href="/latest/api/cpp/class/atmo-server-rendering-renderingplatform" class="atmo-ref atmo-ref--symbol"><code>RenderingPlatform</code></a>, one per GPU API. The engine ships three:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Built by default on</th><th>Purpose</th></tr></thead><tbody><tr><td>Metal</td><td>macOS</td><td>The macOS backend</td></tr><tr><td>Vulkan</td><td>Windows, Linux</td><td>The Windows and Linux backend, opt-in on macOS (MoltenVK)</td></tr><tr><td>Null</td><td>every OS</td><td>Draws nothing; used by <code>--headless</code></td></tr></tbody></table><p>There is no Direct3D 12 platform: Vulkan is the Windows backend. D3D12 is planned for later.</p><h2 id="selection" tabindex="-1">How a platform is chosen <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;How a platform is chosen {#selection}&quot;">​</a></h2><p>The engine picks the best platform for the machine it runs on:</p><table tabindex="0"><thead><tr><th>OS</th><th>Tried in order</th></tr></thead><tbody><tr><td>macOS</td><td>Metal, Vulkan, Null</td></tr><tr><td>Windows</td><td>Vulkan, Null</td></tr><tr><td>Linux</td><td>Vulkan, Null</td></tr></tbody></table><p>A platform is skipped when it is not built or when the GPU lacks what it needs. A platform that only finds a software rasterizer (such as lavapipe) is used only if no other platform has a real GPU. If no GPU platform can start outside headless mode, the engine shows an error dialog and quits instead of opening an empty window.</p><p><code>--rendering-platform=metal|vulkan|null</code> asks for a specific platform; if it is unavailable, the engine falls back to the automatic choice.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xmake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> atmo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rendering-platform=vulkan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --gpu-validation</span></span></code></pre></div><p>Rendering runs on its own thread. <code>--render-thread=off</code> runs it on the main thread, for debugging.</p><h2 id="metal" tabindex="-1">Metal <a class="header-anchor" href="#metal" aria-label="Permalink to &quot;Metal {#metal}&quot;">​</a></h2><ul><li>Needs macOS 13 or later and a GPU in the Metal 3 family with tier 2 argument buffers: every Apple silicon Mac and the recent AMD and Intel GPUs. Older Macs fall back to Vulkan when it is built, otherwise to Null.</li><li>Built by default on macOS; <code>xmake f --rendering_metal=n</code> turns it off. It uses <a href="https://developer.apple.com/metal/cpp/" target="_blank" rel="noreferrer">metal-cpp</a>, so it is plain C++ with no Objective-C.</li><li>Shaders are embedded as Metal source and compiled by the system when the engine starts.</li><li>On macOS 15 and later, resources are kept resident with a residency set; on macOS 13 and 14 they are declared on every render pass instead. <code>ATMO_METAL_RESIDENCY_SETS=0</code> forces the macOS 13 path, for testing.</li></ul><h2 id="vulkan" tabindex="-1">Vulkan <a class="header-anchor" href="#vulkan" aria-label="Permalink to &quot;Vulkan {#vulkan}&quot;">​</a></h2><ul><li>Needs a Vulkan 1.3 driver with dynamic rendering, synchronization2 and descriptor indexing. On Windows, the driver from the GPU vendor (NVIDIA, AMD, Intel, Qualcomm) provides it; the generic Microsoft display driver used by some virtual machines and remote sessions has no Vulkan.</li><li>Built by default on Windows and Linux; <code>xmake f --rendering_vulkan=n</code> builds without it.</li><li>Opt-in on macOS, because it needs MoltenVK (a long first build that requires Xcode) and Metal is the macOS backend. Run <code>xmake f --rendering_vulkan=y</code> once, then start the engine with <code>--rendering-platform=vulkan</code>. The build copies <code>libMoltenVK.dylib</code> next to the binary. A Vulkan loader installed on the system (for example from the Vulkan SDK) is used first, which is what makes <code>--gpu-validation</code> work.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not commit the <code>xmake-requires.lock</code> changes that <code>--rendering_vulkan=y</code> causes on macOS: the lock file matches the default configuration of each platform.</p></div><h2 id="pipeline-cache" tabindex="-1">Pipeline cache <a class="header-anchor" href="#pipeline-cache" aria-label="Permalink to &quot;Pipeline cache {#pipeline-cache}&quot;">​</a></h2><p>Compiled pipelines are cached in <code>~/Library/Application Support/Atmo/Atmo/pipeline-cache/</code> on macOS. Vulkan keeps its cache in the same folder (<code>vulkan-pipelines.bin</code>) and discards it when the GPU or driver changes. The folder can be deleted at any time.</p><h2 id="gpu-validation" tabindex="-1">GPU validation <a class="header-anchor" href="#gpu-validation" aria-label="Permalink to &quot;GPU validation {#gpu-validation}&quot;">​</a></h2><p><code>--gpu-validation</code> turns on the platform&#39;s validation layer:</p><ul><li><strong>Metal</strong> — API and shader validation (<code>MTL_DEBUG_LAYER</code>, <code>MTL_SHADER_VALIDATION</code>). Frames can be captured with Xcode&#39;s GPU debugger.</li><li><strong>Vulkan</strong> — needs the Khronos validation layer (<code>VK_LAYER_KHRONOS_validation</code>) to be installed.</li></ul>',21)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
